//! Direct captured primitive field, shape and cardinality observations.
use serde_json::{Value, json};
fn payload(v: &serde_json::Value) -> safe_cex_venue_cryptocom::ws_payloads::PayloadValue {
    use safe_cex_venue_cryptocom::ws_payloads::PayloadValue as P;
    match v["k"].as_str().unwrap() {
        "u" => P::Undefined,
        "null" => P::Null,
        "b" => P::Bool(v["v"].as_bool().unwrap()),
        "n" => P::Number(f64::from_bits(
            u64::from_str_radix(v["v"].as_str().unwrap(), 16).unwrap(),
        )),
        "s" => P::String(
            v["v"]
                .as_array()
                .unwrap()
                .iter()
                .map(|n| u16::try_from(n.as_u64().unwrap()).unwrap())
                .collect(),
        ),
        "a" => P::Array(v["v"].as_array().unwrap().iter().map(payload).collect()),
        "o" => P::Object(
            v["v"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, v)| (k.encode_utf16().collect(), payload(v)))
                .collect(),
        ),
        _ => panic!("unclassified captured primitive fixture"),
    }
}
